	mux.HandleFunc("GET /v1/documents/{documentID}/crdt/state", func(w http.ResponseWriter, r *http.Request) {
		handleCRDTState(s, w, r)
	})
	mux.HandleFunc("POST /v1/documents/{documentID}/crdt/compact", func(w http.ResponseWriter, r *http.Request) {
		handleCRDTCompact(s, w, r)
	})
	mux.HandleFunc("GET /v1/documents/{documentID}/crdt/snapshot", func(w http.ResponseWriter, r *http.Request) {
		handleCRDTSnapshot(s, w, r)
	})
	// Other verbs on the CRDT endpoints get a JSON 400 (the ops and compact
	// endpoints only accept POST; the state and snapshot endpoints only accept
	// GET) rather than ServeMux's plain-text 405.
	mux.HandleFunc("/v1/documents/{documentID}/crdt/ops", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	mux.HandleFunc("/v1/documents/{documentID}/crdt/state", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	mux.HandleFunc("/v1/documents/{documentID}/crdt/compact", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	mux.HandleFunc("/v1/documents/{documentID}/crdt/snapshot", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})

	// ServeMux treats any empty path segment (the doubled slash in
	// /v1/documents//..., /v1/devices//sessions or
	// /v1/sessions//documents/...) as an unclean path and answers with a 307
	// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
	// error for an empty identifier, so intercept those paths before the mux
	// sees them. A trailing slash empties the final id of the device/session
	// routes and is rejected there for the same reason; the document routes
	// keep their pre-existing ServeMux behavior.
	return emptyIDGuard(mux)
}

// emptyIDGuard rejects requests carrying an empty path identifier with a 400
// JSON error instead of letting ServeMux emit its HTML redirect or a
// plain-text 404.
//
// The document family keeps its original rule (an empty documentID, i.e. the
// prefix /v1/documents//); other odd paths there retain their old response so
// the pre-existing surface is unchanged. The new device/session families are
// stricter: any doubled slash (an empty deviceId, sessionId or documentId
// segment) or a trailing slash (an empty final id) is a 400 JSON error.
func emptyIDGuard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := r.URL.Path

		documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
		newFamilySegmentEmpty := false
		if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
			newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
		}

		if documentSegmentEmpty || newFamilySegmentEmpty || malformedNewDocumentPath(p) || malformedSubscribePath(p) || malformedSessionCRDTPath(p) || malformedCRDTPath(p) {
			writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
			return
		}
		next.ServeHTTP(w, r)
	})
}

// malformedNewDocumentPath reports whether p targets one of the new
// long-poll/replay endpoints but is not that endpoint's exact location: a
// missing/empty segment, a trailing slash, extra segments, or a "poll"/"replay"
// segment in a position short of the registered shape. ServeMux would answer
// those with a 301 redirect or a plain-text 404/405; the new endpoints promise
// a JSON error and never a redirect, so every such path is a malformed 400.
//
// Keywords are matched only past the documentID position, so documents that
// happen to be named "poll" or "replay" keep their ordinary merge/snapshot/
// changes routes.
func malformedNewDocumentPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")

	// Poll endpoint: "poll" must be exactly the third segment, after a
	// non-empty documentID and "changes".
	for i, seg := range segs {
		if seg == "poll" && i > 0 {
			return !(len(segs) == 3 && segs[0] != "" && segs[1] == "changes")
		}
	}
	// Replay endpoint: "replay" must be exactly the second segment, after a
	// non-empty documentID.
	for i, seg := range segs {
		if seg == "replay" && i > 0 {
			return !(len(segs) == 2 && segs[0] != "")
		}
	}
	return false
}

// malformedSubscribePath reports whether p targets the WebSocket subscription
// endpoint but is not at its exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe): a
// missing "documents"/"changes" segment, an extra segment, or a "subscribe"
// segment short of the registered shape. ServeMux would answer those with a
// plain-text 404/405; every failure of this endpoint must be a JSON 400
// instead. Empty segments are already rejected by the guard itself.
//
// "subscribe" is treated as the endpoint keyword only in the endpoint's
// terminal segment position (the fifth segment, index 4); a session or
// document identifier literally named "subscribe" occupies an identifier
// position (index 0 or 2) and is therefore left to the ordinary
// changes/subscribe routes like any other id.
func malformedSubscribePath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "subscribe" there is not the changes-subscribe
	// keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	for i, seg := range segs {
		if seg != "subscribe" {
			continue
		}
		// Identifier positions: sessionId (0) and documentId (2). A value of
		// "subscribe" there is an ordinary identifier, not the endpoint word.
		if i == 0 || i == 2 {
			continue
		}
		// Endpoint keyword position: the fifth segment must be exactly
		// "subscribe" with the documents/changes scaffolding around it, and no
		// segment may follow. Any other occurrence is a malformed path.
		if i == 4 && len(segs) == 5 &&
			segs[0] != "" &&
			segs[1] == "documents" &&
			segs[2] != "" &&
			segs[3] == "changes" {
			return false
		}
		return true
	}
	return false
}

// malformedSessionCRDTPath reports whether p targets the session-scoped CRDT
// namespace but is not at one of its two exact locations:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state/subscribe
//
// a missing "state"/"subscribe" segment, an extra segment, or a "crdt" segment
// in the keyword position (immediately past the document identifier) short of
// one of the registered shapes. ServeMux would answer those with a
// plain-text 404/405; every failure of these endpoints must be a JSON 400
// instead. Empty segments are already rejected by the guard itself.
//
// "crdt" is treated as the endpoint keyword only in the fourth segment (index
// 3, right after the document identifier); a session or document identifier
// literally named "crdt" occupies an identifier position (index 0 or 2) and
// keeps its ordinary routes.
func malformedSessionCRDTPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	if len(segs) < 4 || segs[1] != "documents" || segs[3] != "crdt" {
		return false
	}
	// Keyword position reached. The state read is exactly
	// {sessionId}/documents/{documentId}/crdt/state; the subscription adds
	// one trailing "subscribe" segment.
	validState := len(segs) == 5 &&
		segs[0] != "" &&
		segs[2] != "" &&
		segs[4] == "state"
	validSubscribe := len(segs) == 6 &&
		segs[0] != "" &&
		segs[2] != "" &&
		segs[4] == "state" &&
		segs[5] == "subscribe"
	return !(validState || validSubscribe)
}

// Handler exposes the HTTP surface over a private in-memory store. Use
// NewHandler with a durable store for real deployments.
func Handler() http.Handler {
	s, err := store.Open("")
	if err != nil {
		log.Fatalf("open in-memory store: %v", err)
	}
	return NewHandler(s)
}

// decodeJSONBody enforces the strict POST contract shared by every JSON
// endpoint: Content-Type must be application/json, the body is capped at
// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
// may follow it. Any violation writes a 400 JSON error and returns false; the
// caller returns immediately, so no handler reaches the store with malformed
// input and rejected requests write nothing.
func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return false
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(dst); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return false
	}
	// Reject trailing data after the JSON value.
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return false
	}
	return true
}

func handleRegisterDevice(s *store.Store, w http.ResponseWriter, r *http.Request) {
	var req deviceRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}

	created, err := s.RegisterDevice(req.DeviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to register device")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
}

func handleCreateSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty

	var req sessionRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.SessionID == "" {
		writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
		return
	}

	created, err := s.CreateSession(deviceID, req.SessionID)
	if err != nil {
		var conflict *store.ErrSessionConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
		default:
			writeError(w, http.StatusInternalServerError, "failed to create session")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
}

func handleDeleteSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")   // route pattern + guard guarantee non-empty
	sessionID := r.PathValue("sessionId") // route pattern + guard guarantee non-empty

	if err := s.DeleteSession(deviceID, sessionID); err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to delete session")
		return
	}

	writeJSON(w, http.StatusOK, map[string]bool{"deleted": true})
}

func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req postRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	// Reject trailing data after the JSON object.
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if len(req.Changes) == 0 {
		writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
		return
	}

	changes := make([]store.Change, len(req.Changes))
	seen := make(map[string]struct{}, len(req.Changes))
	for i, c := range req.Changes {
		if c.ID == "" {
			writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
			return
		}
		if len(c.Payload) == 0 {
			writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
			return
		}
		if _, dup := seen[c.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
			return
		}
		seen[c.ID] = struct{}{}
		changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
	}

	results, err := s.PostChanges(documentID, changes)
	if err != nil {
		var conflict *store.ErrConflict
		if errors.As(err, &conflict) {
			writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to commit changes")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req mergeRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	// baseCursor must be present and a non-negative integer (no fractions,
	// strings, booleans or null).
	if len(req.BaseCursor) == 0 {
		writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
		return
	}
	baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
		return
	}
	if req.Change == nil {
		writeError(w, http.StatusBadRequest, "change must be an object")
		return
	}
	if req.Change.ID == "" {
		writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
		return
	}
	if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
		writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
		return
	}

	result, err := s.MergeChange(documentID, baseCursor, store.Change{
		ID:       req.Change.ID,
		DeviceID: req.DeviceID,
		Payload:  req.Change.Payload,
	})
	if err != nil {
		var conflict *store.ErrConflict
		switch {
		case errors.Is(err, store.ErrStaleCursor):
			writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
			return
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
			return
		default:
			writeError(w, http.StatusInternalServerError, "failed to merge change")
			return
		}
	}

	writeJSON(w, http.StatusOK, result)
}

func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req snapshotPostRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	cursor, ok := parseNonNegativeInt(req.Cursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return
	}
	if len(req.State) == 0 {
		writeError(w, http.StatusBadRequest, "state is required")
		return
	}

	created, err := s.PutSnapshot(documentID, cursor, req.State)
	if err != nil {
		var conflict *store.ErrSnapshotConflict
		switch {
		case errors.Is(err, store.ErrSnapshotBase):
			writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
			return
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "snapshot already exists with a different state")
			return
		default:
			writeError(w, http.StatusInternalServerError, "failed to store snapshot")
			return
		}
	}

	writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
}

func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	cursor, ok := parseCursorPath(r.PathValue("cursor"))
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return
	}

	state, err := s.GetSnapshot(documentID, cursor)
	if err != nil {
		if errors.Is(err, store.ErrSnapshotNotFound) {
			writeError(w, http.StatusNotFound, "snapshot not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load snapshot")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
}

func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req restoreRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.ChangeID == "" {
		writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
		return
	}
	// snapshotCursor must be present and a positive integer (no fractions,
	// strings, booleans, null or zero).
	if len(req.SnapshotCursor) == 0 {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}
	snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}

	result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
	if err != nil {
		var conflict *store.ErrRestoreConflict
		switch {
		case errors.Is(err, store.ErrSnapshotNotFound):
			writeError(w, http.StatusNotFound, "snapshot not found")
			return
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
			return
		default:
			writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
			return
		}
	}

	writeJSON(w, http.StatusOK, result)
}

// handleSetPermission grants or revokes a registered device's access to one
// document. Devices start authorized, so the first revoke is the first write;
// repeating the current state is idempotent (changed=false). A rejected
// request (bad content type, malformed JSON, trailing content, empty or
// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
// unregistered device is a 404 JSON error.
func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	var req permissionRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	var authorized bool
	switch req.Action {
	case "grant":
		authorized = true
	case "revoke":
		authorized = false
	default:
		writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
		return
	}

	changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
	if err != nil {
		if errors.Is(err, store.ErrDeviceNotFound) {
			writeError(w, http.StatusNotFound, "device not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to update permission")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"deviceId":   req.DeviceID,
		"authorized": authorized,
		"changed":    changed,
	})
}

// parseCursorPath reports whether raw is a decimal non-negative integer and
// returns its value. Signs, fractions and other adornments are rejected.
func parseCursorPath(raw string) (int64, bool) {
	if raw == "" {
		return 0, false
	}
	for _, c := range raw {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	n, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		return 0, false
	}
	return n, true
}

// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
	var n int64
	if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
		return 0, false
	}
	// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
	// require the literal to contain no fraction or exponent.
	trimmed := strings.TrimSpace(string(raw))
	if trimmed == "" || trimmed[0] == '-' {
		return 0, false
	}
	for _, c := range trimmed {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	return n, true
}

// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
// strings, booleans, null and negative numbers are rejected.
func parsePositiveInt(raw json.RawMessage) (int64, bool) {
	n, ok := parseNonNegativeInt(raw)
	if !ok || n < 1 {
		return 0, false
	}
	return n, true
}

// isJSONObject reports whether raw decodes to a JSON object (not null, an
// array or a scalar).
func isJSONObject(raw json.RawMessage) bool {
	var m map[string]json.RawMessage
	if err := json.Unmarshal(raw, &m); err != nil || m == nil {
		return false
	}
	return true
}

func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID")

	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}

	changes, nextCursor, err := s.ListChanges(documentID, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list changes")
		return
	}

	writeChangesPage(w, changes, nextCursor)
}

// handleSessionChanges is the session-scoped view of the existing change log:
// both path identifiers must be non-empty (the empty-segment guard rejects
// those before routing) and the session must currently exist, after which the
// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
// the session's device has been revoked permission for the document, which is
// a 403 JSON error with no changes or nextCursor. Revocation only gates this
// read; the change log itself is untouched.
func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Malformed query parameters are a request-shape error (400) checked
	// before the resource lookup (404), matching the snapshot GET ordering.
	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	changes, nextCursor, err := s.ListChanges(documentID, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list changes")
		return
	}

	writeChangesPage(w, changes, nextCursor)
}

// parseChangesQuery parses the shared after/limit pagination parameters,
// writing the documented 400 on an illegal value. It is shared by the
// document-scoped and session-scoped change listings so their query semantics
// cannot drift apart.
func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
	q := r.URL.Query()

	after = 0
	if raw := q.Get("after"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 {
			writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
			return 0, 0, false
		}
		after = v
	}

	limit = defaultListLimit
	if raw := q.Get("limit"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 1 || v > maxListLimit {
			writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
			return 0, 0, false
		}
		limit = v
	}

	return after, limit, true
}

// writeChangesPage renders a change listing page in the shared response shape.
func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
	})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, map[string]string{"error": message})
}

// handlePollChanges is the long-polling entry over the change log.
//
// Query params share the existing change-read constraints: after is a
// non-negative cursor (default 0) and limit is 1..1000 (default 100); waitMs
// is 0..30000 (default 0). Rows already past after return immediately; a known
// document caught up to after parks until the first new commit or the wait
// deadline; an unknown document returns an empty page with cursor 0 at once.
// The response shape is the ordinary page plus a timedOut flag; a deadline
// expiry echoes the caller's cursor and never advances it. A client
// disconnect simply stops the wait and writes nothing.
func handlePollChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	var waitMs int64
	if raw := q.Get("waitMs"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 || v > maxPollWaitMillis {
			writeError(w, http.StatusBadRequest, "waitMs must be an integer between 0 and 30000")
			return
		}
		waitMs = v
	}

	changes, nextCursor, timedOut, err := s.WaitForChanges(
		r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
	)
	switch {
	case errors.Is(err, store.ErrStoreClosing):
		writeError(w, http.StatusServiceUnavailable, "service is shutting down")
		return
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		// The client went away (or, with waitMs bounded, its deadline lapsed
		// at the transport): nothing more to write and nothing was stored.
		return
	case err != nil:
		writeError(w, http.StatusInternalServerError, "failed to poll changes")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
		"timedOut":   timedOut,
	})
}

// handleReplay retries an offline batch against the existing change log. The
// request and per-element semantics mirror POST .../changes — strict
// application/json body, non-empty ids, no in-batch duplicates, idempotent only
// when deviceId and decoded payload match, otherwise 409 reporting the
// conflicting id — with the registration/permission layer enforced first:
// 404 for an unregistered device and 403 for a revoked one, neither exposing
// change content. The whole batch commits in one serialized transaction that
// shares the document's contiguous cursor space with ordinary commits.
func handleReplay(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req replayRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.Operations == nil {
		writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
		return
	}
	if len(req.Operations) == 0 {
		writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
		return
	}

	changes := make([]store.Change, len(req.Operations))
	seen := make(map[string]struct{}, len(req.Operations))
	for i, op := range req.Operations {
		if op.ID == "" {
			writeError(w, http.StatusBadRequest, "each operation must have a non-empty string id")
			return
		}
		if len(op.Payload) == 0 {
			writeError(w, http.StatusBadRequest, "each operation must carry a JSON payload")
			return
		}
		if _, dup := seen[op.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate operation id within batch: "+op.ID)
			return
		}
		seen[op.ID] = struct{}{}
		changes[i] = store.Change{ID: op.ID, DeviceID: req.DeviceID, Payload: op.Payload}
	}

	results, err := s.ReplayChanges(documentID, changes)
	if err != nil {
		var conflict *store.ErrConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.As(err, &conflict):
			writeJSON(w, http.StatusConflict, map[string]string{
				"error":      "operation id already exists with different deviceId or payload",
				"conflictId": conflict.ID,
			})
		default:
			writeError(w, http.StatusInternalServerError, "failed to replay operations")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// crdtOpIn is one element of a CRDT submission. Exactly one content shape is
// meaningful depending on the declared document type: value for a counter,
// elements for a grow-only set, value plus version for a register, action
// plus element for an observed-remove set.
type crdtOpIn struct {
	ID       string          `json:"id"`
	Value    json.RawMessage `json:"value"`
	Elements []string        `json:"elements"`
	Version  json.RawMessage `json:"version"`
	Action   string          `json:"action"`
	Element  string          `json:"element"`
}

// crdtOpsRequest is the body of POST .../crdt/ops.
type crdtOpsRequest struct {
	DeviceID string     `json:"deviceId"`
	Type     string     `json:"type"`
	Ops      []crdtOpIn `json:"ops"`
}

// handleCRDTOps accepts a batch of CRDT operations for a document.
//
// The batch declares the document's type; the first accepted batch fixes it
// to counter, gset, register or orset and every later batch must declare the
// same type. Two batches racing to declare different types serialize in one
// transaction: exactly one takes effect and the other is a 409 that writes
// nothing.
//
// The strict body contract matches the other JSON endpoints: application/json,
// one JSON value, no trailing content, a non-empty deviceId, a valid type, a
// non-empty ops array of elements with non-empty ids, no in-batch duplicate
// ids, and type-correct content (counter: an integer value; gset: an elements
// array; register: any JSON value — null included — plus a non-negative
// integer version; orset: action "add" or "remove" plus a non-empty string
// element). Any violation is a 400 with zero writes.
func handleCRDTOps(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req crdtOpsRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.Type != store.CRDTTypeCounter && req.Type != store.CRDTTypeGSet && req.Type != store.CRDTTypeRegister && req.Type != store.CRDTTypeORSet {
		writeError(w, http.StatusBadRequest, `type must be "counter", "gset", "register" or "orset"`)
		return
	}
	if len(req.Ops) == 0 {
		writeError(w, http.StatusBadRequest, "ops must be a non-empty array")
		return
	}

	ops := make([]store.CRDTOp, len(req.Ops))
	seen := make(map[string]struct{}, len(req.Ops))
	for i, op := range req.Ops {
		if op.ID == "" {
			writeError(w, http.StatusBadRequest, "each op must have a non-empty string id")
			return
		}
		if _, dup := seen[op.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate op id within batch: "+op.ID)
			return
		}
		seen[op.ID] = struct{}{}

		crdtOp := store.CRDTOp{ID: op.ID, DeviceID: req.DeviceID}
		switch req.Type {
		case store.CRDTTypeCounter:
			v, ok := parseNonNegativeInt(op.Value)
			if !ok {
				writeError(w, http.StatusBadRequest, "each counter op must carry an integer value >= 0")
				return
			}
			// Re-marshal the canonical integer so idempotency compares the
			// decoded value rather than the client's literal formatting.
			raw, _ := json.Marshal(v)
			crdtOp.Value = raw
		case store.CRDTTypeGSet:
			if len(op.Elements) == 0 {
				writeError(w, http.StatusBadRequest, "each gset op must add at least one element")
				return
			}
			for _, element := range op.Elements {
				if element == "" {
					writeError(w, http.StatusBadRequest, "gset elements must be non-empty strings")
					return
				}
			}
			crdtOp.Elements = op.Elements
		case store.CRDTTypeRegister:
			// The value may be any JSON, null included; only an absent field
			// (a nil RawMessage — an explicit null decodes to the bytes
			// "null") is a missing field. The value is stored verbatim.
			if op.Value == nil {
				writeError(w, http.StatusBadRequest, "each register op must carry a value")
				return
			}
			v, ok := parseNonNegativeInt(op.Version)
			if !ok {
				writeError(w, http.StatusBadRequest, "each register op must carry an integer version >= 0")
				return
			}
			crdtOp.Value = op.Value
			crdtOp.Version = v
		case store.CRDTTypeORSet:
			if op.Action != store.CRDTORSetAdd && op.Action != store.CRDTORSetRemove {
				writeError(w, http.StatusBadRequest, `each orset op must carry action "add" or "remove"`)
				return
			}
			if op.Element == "" {
				writeError(w, http.StatusBadRequest, "each orset op must carry a non-empty string element")
				return
			}
			crdtOp.Action = op.Action
			crdtOp.Element = op.Element
		}
		ops[i] = crdtOp
	}

	results, err := s.SubmitCRDTOps(documentID, req.Type, ops)
	if err != nil {
		var conflict *store.ErrCRDTConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, conflict.Error())
		default:
			writeError(w, http.StatusInternalServerError, "failed to commit crdt ops")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

// handleCRDTState returns the document's current type and merged result. A
// document with no committed operations has no state yet and answers 404.
func handleCRDTState(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	state, err := s.GetCRDTState(documentID)
	if err != nil {
		if errors.Is(err, store.ErrCRDTNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt state")
		return
	}

	writeCRDTState(w, state)
}

// handleSessionCRDTState is the session-scoped view of the document-level
// state read:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state
//
// The read identity is entirely the existing session (no new auth): the
// session's owning device is the credential and the validation order matches
// the other session-scoped reads exactly — request shape (400, enforced by the
// route and path guard before this handler), then session existence
// (404 JSON for a session that never existed or was deleted), then the
// session device's permission for the document (403 JSON with no state
// content), and finally the document's CRDT state. A document without any
// committed CRDT operation is the same 404 JSON as the document-level read, so
// a deleted session, an unknown document-state and a revoked permission remain
// three independent answers.
//
// On success the body is byte-for-byte the document-level state read's body
// (writeCRDTState): compact single-line JSON, keys type then value, one
// trailing newline. The endpoint is read-only: it renders the state derived by
// the store without advancing a cursor, writing a change, registering a
// subscription or affecting CRDT type fixation, idempotency or persistence; a
// restart changes neither the answer nor the status codes.
func handleSessionCRDTState(s *store.Store, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	state, err := s.GetCRDTState(documentID)
	if err != nil {
		if errors.Is(err, store.ErrCRDTNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt state")
		return
	}

	writeCRDTState(w, state)
}

// writeCRDTState renders a CRDT state exactly as every state reader must:
// compact single-line JSON with the keys in type, value order, terminated by a
// newline (the json.Encoder output), shared by the document-level read, the
// session-scoped read and — via marshalCRDTState — the subscription push
// frames, so the three can be compared byte-for-byte.
func writeCRDTState(w http.ResponseWriter, state store.CRDTState) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(marshalCRDTState(state))
}

// marshalCRDTState encodes a CRDT state the single way every surface emits it:
// compact single-line JSON with the keys in type, value order and one trailing
// newline. The value is embedded as native JSON (a number, an array, or a
// register's arbitrary JSON value) rather than an escaped blob.
func marshalCRDTState(state store.CRDTState) []byte {
	var buf strings.Builder
	enc := json.NewEncoder(&buf)
	_ = enc.Encode(map[string]any{
		"type":  state.Type,
		"value": json.RawMessage(state.Value),
	})
	return []byte(buf.String())
}

// malformedCRDTPath reports whether p targets the CRDT namespace but is not at
// one of the four exact endpoints:
//
//	POST     /v1/documents/{documentID}/crdt/ops
//	GET      /v1/documents/{documentID}/crdt/state
//	POST     /v1/documents/{documentID}/crdt/compact
//	GET      /v1/documents/{documentID}/crdt/snapshot
//
// A missing/empty document id, a trailing slash, extra path segments, or a
// "crdt" segment in any position short of that shape is a malformed 400 rather
// than ServeMux's redirect or plain-text 404/405, so the new endpoints never
// redirect or emit HTML. The keyword is matched only past the documentID
// position, so a document literally named "crdt" keeps its ordinary routes.
func malformedCRDTPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg == "crdt" && i > 0 {
			if len(segs) != 3 || segs[0] == "" {
				return true
			}
			switch segs[2] {
			case "ops", "state", "compact", "snapshot":
				return false
			default:
				return true
			}
		}
	}
	return false
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strconv"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// crdtCompactRequest is the body of POST .../crdt/compact.
type crdtCompactRequest struct {
	DeviceID string `json:"deviceId"`
}

// handleCRDTCompact trims the document's stored CRDT operations and
// tombstones down to the ones still participating in the merge.
//
// The request contract matches the CRDT submission endpoint: strict
// application/json, exactly one JSON value, no trailing content and a
// non-empty deviceId — any violation is a 400 JSON error with zero writes.
// The device gate then applies in the submission's order: an unregistered
// device is a 404, a device whose permission for the document was revoked is
// a 403, and a document with no committed CRDT operation is a 404; none of
// them writes anything or leaks state content.
//
// On success the answer is 200 with the post-compaction snapshot, rendered
// byte-for-byte like a snapshot read immediately afterward (writeCRDTSnapshot).
// Compaction is idempotent — a repeat trims nothing and returns the same
// body — and touches only the CRDT state layer: it allocates no change
// cursor, writes no change record and, because the merged value never moves,
// pushes no notification.
func handleCRDTCompact(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req crdtCompactRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}

	snapshot, err := s.CompactCRDT(documentID, req.DeviceID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.Is(err, store.ErrCRDTNotFound):
			writeError(w, http.StatusNotFound, "crdt state not found")
		default:
			writeError(w, http.StatusInternalServerError, "failed to compact crdt state")
		}
		return
	}

	writeCRDTSnapshot(w, snapshot)
}

// handleCRDTSnapshot returns the document's merged CRDT state together with
// the number of stored operations and tombstones the merge is derived from.
// The read carries no device identity and adds no authentication: like the
// document-level state read it is open, and a document with no committed CRDT
// operation answers the same 404 JSON as the state read. The read is pure —
// no cursor, no change record, no subscription.
func handleCRDTSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	snapshot, err := s.GetCRDTSnapshot(documentID)
	if err != nil {
		if errors.Is(err, store.ErrCRDTNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt snapshot")
		return
	}

	writeCRDTSnapshot(w, snapshot)
}

// writeCRDTSnapshot renders a CRDT snapshot exactly as both snapshot surfaces
// must emit it: compact single-line JSON with the keys in type, value,
// operations, tombstones order, terminated by a newline, so the compaction
// response and the snapshot read can be compared byte-for-byte.
func writeCRDTSnapshot(w http.ResponseWriter, snapshot store.CRDTSnapshot) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(marshalCRDTSnapshot(snapshot))
}

// marshalCRDTSnapshot encodes a CRDT snapshot the single way both surfaces
// emit it: compact single-line JSON with the keys in type, value, operations,
// tombstones order and one trailing newline. The merged value is embedded as
// native JSON (a number, an array, or a register's arbitrary JSON value)
// rather than an escaped blob, and the two counts are non-negative integers.
// The key order is fixed by construction — not by the encoder's map ordering
// — so the bytes are stable across every reader.
func marshalCRDTSnapshot(snapshot store.CRDTSnapshot) []byte {
	var buf strings.Builder
	typeRaw, _ := json.Marshal(snapshot.Type)
	buf.WriteString(`{"type":`)
	_, _ = buf.Write(typeRaw)
	buf.WriteString(`,"value":`)
	_, _ = buf.Write(snapshot.Value)
	buf.WriteString(`,"operations":`)
	buf.WriteString(strconv.FormatInt(snapshot.Operations, 10))
	buf.WriteString(`,"tombstones":`)
	buf.WriteString(strconv.FormatInt(snapshot.Tombstones, 10))
	buf.WriteString("}\n")
	return []byte(buf.String())
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// subscribePageLimit is the page size used while replaying changes already
// committed after the subscription cursor. It matches the largest page the
// paginated read endpoint accepts, so catch-up and reads stay page-aligned.
const subscribePageLimit = 1000

// wsCloseEchoWait bounds how long a server-initiated close waits for the
// client's close echo before the deferred TCP teardown.
const wsCloseEchoWait = 500 * time.Millisecond

// handleSubscribe is the WebSocket document subscription mounted under the
// session view:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe?cursor=N
//
// The subscription identity is entirely the existing session: the session's
// owning device is the only credential. Validation happens entirely before
// the 101 handshake and writes nothing:
//
//  1. cursor must be a non-negative decimal integer (400 JSON otherwise),
//  2. the request must carry a valid WebSocket upgrade handshake (400 JSON),
//  3. the session must currently exist (404 JSON),
//  4. its device must currently hold permission for the document (403 JSON).
//
// After the upgrade the server first sends every committed change with a
// cursor greater than the starting cursor — paged in cursor order, one text
// frame per record in the exact {"id","deviceId","payload","cursor"} shape of
// a paginated read row — then seamlessly continues with changes committed by
// any write path (batch post, merge, restore, replay). Frames are never
// reordered or coalesced; a later read from the last observed cursor returns
// the same rows. The connection is push-only: inbound data frames are read
// and discarded, only close/ping control frames are honored.
//
// A permission revoked after the upgrade ends the subscription with close
// code 4403 and no further frame follows; a termination signal ends every
// subscription with 1001. A client disconnect simply unregisters — like long
// polling, a subscription writes no change, cursor or other record.
func handleSubscribe(s *store.Store, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Parameter shape first: a bad cursor is a 400 even when the session or
	// handshake is also bad, matching the session-scoped read ordering.
	cursor, ok := parseSubscribeCursor(w, r)
	if !ok {
		return
	}
	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 response could not be written and the connection has been
		// hijacked (or is gone), so no JSON error can be produced. Nothing
		// was registered or written to the store.
		return
	}

	serveSubscription(r, s, conn, documentID, deviceID, cursor)
}

// parseSubscribeCursor validates the mandatory cursor query parameter: it
// must be present and a decimal non-negative integer. Negative, fractional
// and non-numeric values are a 400 JSON error; signs and adornments are
// rejected.
func parseSubscribeCursor(w http.ResponseWriter, r *http.Request) (int64, bool) {
	raw := r.URL.Query().Get("cursor")
	// parseCursorPath accepts only decimal digits (no sign, fraction or
	// exponent); a missing parameter is an empty raw and is rejected too.
	cursor, ok := parseCursorPath(raw)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return 0, false
	}
	return cursor, true
}

// serveSubscription runs one upgraded connection to completion. It registers
// before the first log read (a commit landing during catch-up is therefore
// never missed), then alternates a flush phase — drain every page of changes
// past the last sent cursor — and a park phase on the wake channel. A revoke
// is acted on only after the committed tail is flushed, so a commit that was
// authorized when it landed is still delivered ahead of the 4403. The method
// returns when the client leaves, permission is revoked or the store starts
// closing; the hijacked connection is closed on exit.
func serveSubscription(r *http.Request, s *store.Store, conn *wsConn, documentID, deviceID string, cursor int64) {
	// Registration precedes the first read: the wake channel is buffered, so
	// a commit during a read leaves a pending wake that makes the next park
	// return immediately — no wake is lost. The revoked channel closes once
	// if access is withdrawn, and that event survives a racing re-grant.
	wakeCh, revokedCh, unregister := s.AddSubscription(documentID, deviceID)
	defer func() {
		unregister()
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				// A malformed frame ends the connection with the RFC
				// protocol-error code; a client close is already echoed
				// inside ReadMessage; a network drop needs no frame.
				var protoErr *wsProtocolErrorString
				if errors.As(err, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only channel: an inbound data frame is read and
			// discarded; the client cannot mutate the log over it.
		}
	}()

	// checkEnd non-blockingly maps a closing store to 1001 and a sticky
	// revoke to 4403; it returns true when the subscription must end. A
	// termination signal takes precedence: SIGTERM must end every
	// subscription with 1001 even if a revoke is also pending.
	checkEnd := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-revokedCh:
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	position := cursor
	first := true
	for {
		if !first {
			// Park until a commit, a sticky revoke or the termination signal
			// wakes us. r.Context() covers a non-shutdown cancel; the read
			// pump covers a client disconnect.
			select {
			case <-wakeCh:
				// Drain any coalesced follow-up signal as well; the flush
				// below reconciles every case by re-reading from the last
				// sent cursor.
				select {
				case <-wakeCh:
				default:
				}
			case <-revokedCh:
				if s.Closing() {
					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
					return
				}
				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
				return
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			}
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
		}
		first = false

		// Flush phase: page every change past position in cursor order. A
		// termination signal or a revoke is honored between pages/rows so a
		// large catch-up cannot delay the closing frame. A revoke arriving
		// while the final already-authorized tail is in flight is checked
		// after the inner loop, so that tail still goes out first.
		for {
			if checkEnd() {
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}

			changes, _, err := s.ListChanges(documentID, position, subscribePageLimit)
			if err != nil {
				_ = conn.Close(wsCloseInternalError, "internal error")
				return
			}
			for i := range changes {
				if checkEnd() {
					return
				}
				raw, marshalErr := json.Marshal(changes[i])
				if marshalErr != nil {
					_ = conn.Close(wsCloseInternalError, "internal error")
					return
				}
				if writeErr := conn.WriteText(raw); writeErr != nil {
					return
				}
				position = changes[i].Cursor
			}
			if len(changes) < subscribePageLimit {
				break
			}
		}

		// Caught up. A revoke that arrived during the last page (its tail was
		// just flushed) now ends the subscription; otherwise loop and park.
		// Closing still wins over a pending revoke.
		if checkEnd() {
			return
		}
	}
}

// endSubscription sends the mandated closing frame and briefly waits for the
// read pump to observe the peer's close echo, so a graceful close reaches the
// client instead of being truncated by the deferred TCP teardown. It returns
// promptly if the peer is already gone; the caller's deferred NetClose drops
// the socket either way.
func endSubscription(conn *wsConn, clientGone <-chan struct{}, code int, reason string) {
	_ = conn.Close(code, reason)
	timer := time.NewTimer(wsCloseEchoWait)
	defer timer.Stop()
	select {
	case <-clientGone:
	case <-timer.C:
	}
}

