// A subscription opened while the store is closing is signaled immediately.
func TestSubscriptionAddedWhileClosing(t *testing.T) {
	s, _ := Open("")
	s.InterruptWaits()
	ch, _, unregister := s.AddSubscription("doc", "dev-1")
	defer unregister()
